import adsk.core
import adsk.fusion
import adsk.cam
import time

MM = 10.0  # 1 cm = 10 mm; Fusion internal length is cm, feed cm/min.


# ── env ────────────────────────────────────────────────────────────────

def _app():
    return adsk.core.Application.get()


def _doc():
    return _app().activeDocument


def get_cam(activate=True):
    """The CAM product for the active doc, activating Manufacturing if needed.

    cam.products.itemByProductType RAISES (not None) when CAM isn't initialised;
    we activate the CAMEnvironment workspace once and re-fetch."""
    doc = _doc()
    try:
        cam = doc.products.itemByProductType("CAMProductType")
    except Exception:
        cam = None
    if cam is None and activate:
        try:
            ws = _app().userInterface.workspaces.itemById("CAMEnvironment")
            if ws:
                ws.activate()
                adsk.doEvents()
            cam = doc.products.itemByProductType("CAMProductType")
        except Exception:
            cam = None
    if cam is None:
        raise RuntimeError("CAM product unavailable (could not initialise Manufacturing)")
    return cam


def _design():
    return adsk.fusion.Design.cast(_doc().products.itemByProductType("DesignProductType"))


def _root():
    return _design().rootComponent


def _all_bodies():
    return list(_root().bRepBodies)


# ── inspection (cheap, structured) ─────────────────────────────────────

def inspect():
    """Compact scene summary: units, bodies (dims/bbox in mm), CAM setups.

    One call replaces a pile of exploration scripts. Returns a JSON-able dict."""
    doc = _doc()
    out = {"document": doc.name, "length_unit": "mm", "bodies": [], "cam": {}}
    for i, b in enumerate(_all_bodies()):
        bb = b.boundingBox
        mn, mx = bb.minPoint, bb.maxPoint
        out["bodies"].append({
            "index": i,
            "name": b.name,
            "dims_mm": [round((mx.x - mn.x) * MM, 3),
                        round((mx.y - mn.y) * MM, 3),
                        round((mx.z - mn.z) * MM, 3)],
            "bbox_min_mm": [round(mn.x * MM, 3), round(mn.y * MM, 3), round(mn.z * MM, 3)],
            "bbox_max_mm": [round(mx.x * MM, 3), round(mx.y * MM, 3), round(mx.z * MM, 3)],
            "face_count": b.faces.count,
        })
    try:
        cam = get_cam(activate=False)
        out["cam"] = {"present": True, "setups": [s.name for s in cam.setups]}
    except Exception:
        out["cam"] = {"present": False, "setups": []}
    return out


def _face_type(face):
    geo = face.geometry
    name = type(geo).__name__  # Plane, Cylinder, Cone, Sphere, Torus, NurbsSurface
    return name.replace("adsk.core.", "")


def faces(body_index=0, kind=None):
    """Faces of a body as compact dicts: index, type, area_mm2, centroid_mm, normal,
    z_mm. `kind` optionally filters by type substring (e.g. "Plane", "Cylinder").

    The face `index` is stable for the static part body, so the model selects
    machining geometry by passing these indices to add_operation(geometry=...)."""
    bodies = _all_bodies()
    if body_index < 0 or body_index >= len(bodies):
        raise RuntimeError(f"body_index {body_index} out of range (have {len(bodies)})")
    body = bodies[body_index]
    res = []
    for i in range(body.faces.count):
        f = body.faces.item(i)
        ftype = _face_type(f)
        if kind and kind.lower() not in ftype.lower():
            continue
        entry = {"index": i, "type": ftype, "area_mm2": round(f.area * MM * MM, 3)}
        try:
            pt = f.pointOnFace
            entry["centroid_mm"] = [round(pt.x * MM, 3), round(pt.y * MM, 3), round(pt.z * MM, 3)]
